package com.prakash.gmcemp.shipment.controller;import com.prakash.gmcemp.shipment.dto.*;import com.prakash.gmcemp.shipment.model.*;import com.prakash.gmcemp.shipment.service.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/shipments") public class ShipmentController{private final ShipmentService service;public ShipmentController(ShipmentService s){service=s;}@PostMapping ResponseEntity<Shipment> create(@Valid @RequestBody ShipmentRequest r){return ResponseEntity.status(201).body(service.create(r));}@GetMapping("/{id}") Shipment get(@PathVariable Long id){return service.get(id);}@GetMapping List<Shipment> all(){return service.all();}@PutMapping("/{id}") Shipment update(@PathVariable Long id,@Valid @RequestBody ShipmentRequest r){return service.update(id,r);}}